// Every [deskdev] workflow names this one as settings.errorWorkflow, so any
// failed production execution lands here exactly once. Two outputs:
//   1. an `error` row in automation_runs (what Settings → Integrations reads)
//   2. an email, so a failure is seen the day it happens, not the day someone
//      notices a digest stopped arriving.
const ALERT_TO = 'nixgensolutions@gmail.com';

const e = $input.first().json;
const wf = e.workflow || {};
const ex = e.execution || {};
// A failure inside the trigger itself arrives as e.trigger.error instead.
const err = ex.error || (e.trigger && e.trigger.error) || {};
const name = wf.name || 'unknown workflow';
// "[deskdev] overdue-tasks" -> "overdue-tasks" (the automation_jobs key)
const job = name
  .replace(/^\[deskdev\]\s*/i, '')
  .toLowerCase()
  .replace(/[^a-z0-9-]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 64) || 'unknown';
const message = String(err.message || 'Unknown error').slice(0, 500);
const node = ex.lastNodeExecuted || (err.node && err.node.name) || '';
const url = ex.url || '';

// Alert at most once per job per hour. log-to-sheets runs on every task and notification
// insert, so a broken Sheets credential would otherwise send one email per
// insert. Every failure is still logged to automation_runs; only the email is
// throttled. Static data persists across production executions.
const QUIET_MS = 60 * 60 * 1000;
const store = $getWorkflowStaticData('global');
store.lastAlertAt = store.lastAlertAt || {};
const now = Date.now();
const email = !store.lastAlertAt[job] || now - store.lastAlertAt[job] > QUIET_MS;
if (email) store.lastAlertAt[job] = now;

const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const html = `<div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#111">
  <h2 style="margin:0 0 8px;color:#b91c1c">${esc(name)} failed</h2>
  <p style="margin:0 0 4px"><b>Node:</b> ${esc(node || 'n/a')}</p>
  <p style="margin:0 0 12px"><b>Error:</b> ${esc(message)}</p>
  ${url ? `<p><a href="${esc(url)}">Open the execution in n8n</a></p>` : ''}
  <p style="margin-top:16px;color:#888;font-size:12px">Logged to automation_runs. DeskDev shows it under Settings → Integrations.</p>
</div>`;

return [{ json: {
  job,
  workflow: name,
  execution_id: ex.id ? String(ex.id) : null,
  node,
  message,
  url,
  to: ALERT_TO,
  subject: `DeskDev automation failed: ${name}`,
  html,
  email,
} }];

// Only the first failure per job per hour gets an email (decided in Build).
const b = $('Build').first().json;
return b.email ? [{ json: b }] : [];
